function addProp(typeID , value)
{
	var porp = new tw.object.ECMProperty();
	porp.objectTypeId = typeID;
	porp.value = value;
	tw.local.properties.insertIntoList(tw.local.properties.listLength, porp);
}

addProp(""+tw.epv.ECMProperties.arabicName , tw.local.customerName);
addProp(""+tw.epv.ECMProperties.customerCIF , tw.local.CIF);
addProp(""+tw.epv.ECMProperties.branchCode , tw.local.branchCode);
addProp(""+tw.epv.ECMProperties.customerType , ""+tw.epv.ECMProperties.Corporate);

